/** Native file selection, combined filters and local search; no cloud or microphone access. */
public final class MainActivity extends Activity {
    private static final int FILES=10,TREE=11,EXPORT=12;
    AlertDialog languageDialog;String language="ru";Library library;LinearLayout root,filesPage,searchPage,fileList,resultList;EditText nameFilter,dateFrom,dateTo,sizeMin,sizeMax,query;Spinner mode,speech;CheckBox fuzzy;TextView count,status;Button run,stop;List<Library.Entry> visible=new ArrayList<>();List<Result> matches=new ArrayList<>();boolean running=false,scanning=false;int anchor=-1;MediaPlayer player;Handler handler=new Handler(Looper.getMainLooper());String csv="";
    static class Result {Library.Entry file;double start,end;String excerpt,summary;Result(Library.Entry f,double a,double b,String text){file=f;start=a;end=b;excerpt=text;summary=text.length()>150?text.substring(0,150)+"…":text;}}
    String t(String ru,String en){return language.equals("ru")?ru:en;}
    int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    TextView text(String value,int size){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(Color.rgb(36,58,74));v.setPadding(0,dp(6),0,dp(6));return v;}
    Button button(String value,Runnable action){Button b=new Button(this);b.setText(value);b.setAllCaps(false);b.setOnClickListener(v->action.run());return b;}
    LinearLayout column(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);return c;}
    LinearLayout row(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.HORIZONTAL);return c;}
    EditText edit(String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setTextSize(14);return e;}
    void weighted(LinearLayout row,View v){row.addView(v,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1));}
    void watch(EditText e,Runnable callback){e.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){callback.run();}public void afterTextChanged(Editable e){}});}
    final BroadcastReceiver events=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(status==null)return;status.setText(i.getStringExtra("message"));if(i.getBooleanExtra("done",false)){running=false;updateButtons();refreshFiles();search();}}};
    @Override public void onCreate(Bundle saved){super.onCreate(saved);library=new Library(this);language=getPreferences(0).getString("language","ru");if(Build.VERSION.SDK_INT>=33)registerReceiver(events,new IntentFilter(RecognitionService.EVENT),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(events,new IntentFilter(RecognitionService.EVENT));
        languageDialog=new AlertDialog.Builder(this).setTitle("AudioDetect · Language / Язык").setItems(new String[]{"Русский","English"},(d,which)->{language=which==0?"ru":"en";getPreferences(0).edit().putString("language",language).apply();build();}).setCancelable(false).create();languageDialog.show();
    }
    void build(){
        root=column();root.setBackgroundColor(Color.rgb(244,247,249));root.setPadding(dp(16),dp(12),dp(16),dp(10));setContentView(root);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
        root.setOnApplyWindowInsetsListener((view,insets)->{view.setPadding(dp(16),dp(12)+insets.getSystemWindowInsetTop(),dp(16),dp(10)+insets.getSystemWindowInsetBottom());return insets;});root.requestApplyInsets();
        TextView title=text("AudioDetect",27);title.setTypeface(null,1);root.addView(title);root.addView(text(t("Поиск в разговорах. Всё остаётся на телефоне.","Search conversations. Everything stays on this phone."),13));
        LinearLayout tabs=row();weighted(tabs,button(t("Записи","Recordings"),()->show(false)));weighted(tabs,button(t("Поиск","Search"),()->show(true)));root.addView(tabs);
        ScrollView scroll=new ScrollView(this);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout content=column();scroll.addView(content);filesPage=column();searchPage=column();content.addView(filesPage);content.addView(searchPage);
        LinearLayout sources=row();weighted(sources,button(t("Выбрать папку","Choose folder"),()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,TREE);}));weighted(sources,button(t("Выбрать файлы","Choose files"),()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("audio/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,FILES);}));filesPage.addView(sources);
        nameFilter=edit(t("Название содержит…","Name contains…"));filesPage.addView(nameFilter);filesPage.addView(text(t("Дата изменения · ГГГГ-ММ-ДД","Modified date · YYYY-MM-DD"),13));LinearLayout dates=row();dateFrom=edit(t("От","From"));dateTo=edit(t("До","Through"));weighted(dates,dateFrom);weighted(dates,dateTo);filesPage.addView(dates);
        LinearLayout sizes=row();sizeMin=edit(t("Минимум, МиБ","Minimum MiB"));sizeMax=edit(t("Максимум, МиБ","Maximum MiB"));sizeMin.setInputType(8194);sizeMax.setInputType(8194);weighted(sizes,sizeMin);weighted(sizes,sizeMax);filesPage.addView(sizes);
        LinearLayout selection=row();weighted(selection,button(t("Отметить список","Check filtered"),()->bulk(true)));weighted(selection,button(t("Снять отметки","Uncheck filtered"),()->bulk(false)));filesPage.addView(selection);
        filesPage.addView(text(t("Фильтры применяются вместе. Долгое нажатие отмечает диапазон от последней выбранной строки. Дата зависит от данных, предоставленных проводником.","Filters apply together. Long-press selects a range from the last tapped row. Dates depend on metadata supplied by the file provider."),12));
        count=text("",14);filesPage.addView(count);fileList=column();filesPage.addView(fileList);
        searchPage.addView(text(t("Что найти в разговорах?","What would you like to find?"),21));query=edit(t("Например: договор сроки оплата","For example: contract deadline payment"));searchPage.addView(query);
        mode=new Spinner(this);mode.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{t("Фраза","Phrase"),t("Все ключевые слова (И)","All keywords (AND)"),t("Любое слово (ИЛИ)","Any keyword (OR)")}));searchPage.addView(mode);
        fuzzy=new CheckBox(this);fuzzy.setText(t("Похожие написания","Similar spellings"));fuzzy.setChecked(true);searchPage.addView(fuzzy);
        searchPage.addView(text(t("Язык речи в записях","Language spoken in recordings"),14));speech=new Spinner(this);speech.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Русский","English"}));speech.setSelection(language.equals("en")?1:0);searchPage.addView(speech);
        searchPage.addView(text(t("Сначала распознаются отмеченные файлы. Повторные запросы используют готовый текст. Все слова могут встречаться в разных частях одной записи.","Checked files are transcribed once. Later searches reuse the text. All keywords may occur in different parts of one recording."),12));
        LinearLayout work=row();run=button(t("Проверить выбранные","Check selected"),this::start);stop=button(t("Стоп","Stop"),this::stop);run.setBackgroundTintList(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_enabled},new int[]{}},new int[]{Color.rgb(11,105,112),Color.rgb(158,186,187)}));run.setTextColor(Color.WHITE);weighted(work,run);weighted(work,stop);searchPage.addView(work);status=text(t("Выберите записи и введите запрос.","Choose recordings and enter a query."),14);searchPage.addView(status);
        LinearLayout actions=row();weighted(actions,button(t("Поиск в готовом тексте","Search saved text"),this::search));weighted(actions,button(t("Таблица CSV","Export CSV"),this::export));searchPage.addView(actions);resultList=column();searchPage.addView(resultList);
        for(EditText e:new EditText[]{nameFilter,dateFrom,dateTo,sizeMin,sizeMax})watch(e,this::refreshFiles);
        ActivityManager am=(ActivityManager)getSystemService(ACTIVITY_SERVICE);for(ActivityManager.RunningServiceInfo s:am.getRunningServices(100))if(s.service.getClassName().equals(RecognitionService.class.getName()))running=true;
        updateButtons();refreshFiles();show(false);
    }
    void show(boolean results){filesPage.setVisibility(results?View.GONE:View.VISIBLE);searchPage.setVisibility(results?View.VISIBLE:View.GONE);if(results&&!running)search();}
    void enableTree(View view,boolean enabled){view.setEnabled(enabled);if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++)enableTree(group.getChildAt(i),enabled);}}
    void updateButtons(){if(run==null)return;run.setEnabled(!running&&!scanning);stop.setEnabled(running);speech.setEnabled(!running);query.setEnabled(!running);mode.setEnabled(!running);fuzzy.setEnabled(!running);enableTree(filesPage,!running&&!scanning);}
    Long date(EditText edit,boolean end)throws Exception{String s=edit.getText().toString().trim();if(s.isEmpty())return null;SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd",Locale.ROOT);f.setLenient(false);ParsePosition p=new ParsePosition(0);Date d=f.parse(s,p);if(d==null||p.getIndex()!=s.length())throw new Exception(t("Проверьте дату: ГГГГ-ММ-ДД","Check date: YYYY-MM-DD"));Calendar c=Calendar.getInstance();c.setTime(d);if(end)c.add(Calendar.DATE,1);return c.getTimeInMillis();}
    double size(EditText edit,double fallback)throws Exception{String s=edit.getText().toString().trim().replace(',','.');if(s.isEmpty())return fallback;double v=Double.parseDouble(s);if(!Double.isFinite(v)||v<0)throw new Exception(t("Проверьте размер","Check size"));return v*1048576;}
    List<Library.Entry> filtered()throws Exception{Long from=date(dateFrom,false),to=date(dateTo,true);double min=size(sizeMin,0),max=size(sizeMax,Double.MAX_VALUE);if(from!=null&&to!=null&&from>=to||min>max)throw new Exception(t("Проверьте диапазон фильтра","Check filter range"));String name=nameFilter.getText().toString().toLowerCase(Locale.ROOT);List<Library.Entry> list=new ArrayList<>();for(Library.Entry e:library.entries()){boolean named=name.trim().isEmpty();for(String part:name.split(";"))if(!part.trim().isEmpty()&&e.name.toLowerCase(Locale.ROOT).contains(part.trim()))named=true;if(!named||e.size<min||e.size>max)continue;if(from!=null&&(e.modified==0||e.modified<from)||to!=null&&(e.modified==0||e.modified>=to))continue;list.add(e);}return list;}
    void refreshFiles(){if(fileList==null)return;fileList.removeAllViews();try{visible=filtered();int selected=0;long bytes=0;for(int i=0;i<visible.size();i++){Library.Entry e=visible.get(i);if(e.selected){selected++;bytes+=e.size;}int index=i;CheckBox box=new CheckBox(this);String modified=e.modified==0?t("Дата неизвестна","Unknown date"):new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.ROOT).format(new Date(e.modified));box.setText(e.name+"\n"+modified+String.format(Locale.ROOT," · %.2f MiB",e.size/1048576.0)+(e.error.isEmpty()?e.text.isEmpty()?"":" · ✓":" · ! "+e.error));box.setTextSize(13);box.setChecked(e.selected);box.setOnCheckedChangeListener((b,checked)->{library.select(e.uri,checked);e.selected=checked;anchor=index;updateCount();});box.setOnLongClickListener(v->{int first=anchor<0?index:Math.min(anchor,index),last=anchor<0?index:Math.max(anchor,index);for(int k=first;k<=last;k++)library.select(visible.get(k).uri,true);refreshFiles();return true;});fileList.addView(box);}updateCount();}catch(Exception e){visible.clear();count.setText(e.getMessage());}}
    void updateCount(){int n=0;long bytes=0;for(Library.Entry e:visible)if(e.selected){n++;bytes+=e.size;}count.setText(t("Показано: ","Shown: ")+visible.size()+t(" · В работу: "," · Selected: ")+n+String.format(Locale.ROOT," · %.2f MiB",bytes/1048576.0));}
    void bulk(boolean check){for(Library.Entry e:visible)library.select(e.uri,check);refreshFiles();}
    void permission(Uri uri,int flags){try{getContentResolver().takePersistableUriPermission(uri,flags&Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}}
    void add(Uri uri)throws Exception{String name="recording",mime="";long size=0,modified=0;try(Cursor c=getContentResolver().query(uri,null,null,null,null)){if(c!=null&&c.moveToFirst()){int col=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(col>=0)name=c.getString(col);col=c.getColumnIndex(OpenableColumns.SIZE);if(col>=0)size=c.getLong(col);col=c.getColumnIndex(DocumentsContract.Document.COLUMN_LAST_MODIFIED);if(col>=0)modified=c.getLong(col);col=c.getColumnIndex(DocumentsContract.Document.COLUMN_MIME_TYPE);if(col>=0)mime=c.getString(col);}}if(mime!=null&&mime.startsWith("audio/")||name.toLowerCase(Locale.ROOT).matches(".*\\.(mp3|wav|m4a|aac|ogg|flac|mp4|wma)$"))library.add(uri.toString(),name,size,modified);}
    void tree(Uri tree,String parent,Set<String> seen)throws Exception{if(!seen.add(parent))return;if(seen.size()>10000)throw new IOException("Folder limit reached");Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,parent);try(Cursor c=getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_MIME_TYPE},null,null,null)){if(c!=null)while(c.moveToNext()){String id=c.getString(0);if(DocumentsContract.Document.MIME_TYPE_DIR.equals(c.getString(1)))tree(tree,id,seen);else add(DocumentsContract.buildDocumentUriUsingTree(tree,id));}}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null)return;if(request==EXPORT){try(OutputStream out=getContentResolver().openOutputStream(data.getData(),"wt")){out.write(csv.getBytes(StandardCharsets.UTF_8));toast(t("Таблица сохранена","Table saved"));}catch(Exception e){toast(e.getMessage());}return;}
        List<Uri> uris=new ArrayList<>();if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)uris.add(data.getData());for(Uri uri:uris)permission(uri,data.getFlags());
        scanning=true;updateButtons();toast(t("Читаем список файлов…","Reading file list…"));new Thread(()->{String error=null;try{for(Uri uri:uris)if(request==TREE)tree(uri,DocumentsContract.getTreeDocumentId(uri),new HashSet<>());else add(uri);}catch(Exception e){error=e.getMessage();}String message=error;runOnUiThread(()->{scanning=false;updateButtons();refreshFiles();if(message!=null)toast(message);});}).start();
    }
    void start(){if(running)return;if(query.getText().toString().trim().isEmpty()){toast(t("Введите запрос","Enter a query"));return;}try{JSONArray uris=new JSONArray();for(Library.Entry e:filtered())if(e.selected)uris.put(e.uri);if(uris.length()==0){toast(t("Отметьте записи","Check some recordings"));return;}JSONObject job=new JSONObject().put("language",speech.getSelectedItemPosition()==0?"ru":"en").put("uris",uris);Files.write(new File(getFilesDir(),"job.json").toPath(),job.toString().getBytes(StandardCharsets.UTF_8));if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},13);startForegroundService(new Intent(this,RecognitionService.class).putExtra("uiLanguage",language));running=true;status.setText(t("Подготовка…","Preparing…"));updateButtons();}catch(Exception e){toast(e.getMessage());}}
    void stop(){if(running){startService(new Intent(this,RecognitionService.class).setAction("STOP"));stop.setEnabled(false);status.setText(t("Остановка…","Stopping…"));}}
    void search(){if(resultList==null)return;resultList.removeAllViews();matches.clear();String q=query.getText().toString().trim();if(q.isEmpty())return;int searchMode=mode.getSelectedItemPosition(),ready=0,pending=0,files=0;String lang=speech.getSelectedItemPosition()==0?"ru":"en";try{for(Library.Entry e:filtered()){if(!e.selected)continue;if(e.text.isEmpty()||!e.language.equals(lang)||!e.error.isEmpty()){pending++;continue;}ready++;if(searchMode>0&&!Search.matches(e.words(),q,searchMode,fuzzy.isChecked()))continue;JSONArray parts=e.segments();int before=matches.size();for(int i=0;i<parts.length();i++){JSONObject part=parts.getJSONObject(i);String excerpt=part.getString("text");double start=part.getDouble("start"),end=part.getDouble("end");boolean hit=Search.matches(excerpt,q,searchMode==1?2:searchMode,fuzzy.isChecked());if(searchMode==0&&!hit&&i+1<parts.length()){JSONObject next=parts.getJSONObject(i+1);if(next.getDouble("start")-end<=8&&next.getDouble("end")-start<=45&&Search.matches(excerpt+" "+next.getString("text"),q,0,fuzzy.isChecked())){hit=true;excerpt+=" "+next.getString("text");end=next.getDouble("end");}}if(hit)matches.add(new Result(e,start,end,excerpt));}if(matches.size()>before)files++;}
        resultList.addView(text(t("Найдено записей: ","Matching recordings: ")+files+t(" · Фрагментов: "," · Excerpts: ")+matches.size()+t("\nРаспознано: ","\nTranscribed: ")+ready+t(" · Ожидают: "," · Pending: ")+pending,16));if(matches.isEmpty())resultList.addView(text(t("Совпадений в готовых расшифровках выбранных записей нет.","No matches in completed transcripts of selected recordings."),14));
        for(Result r:matches){LinearLayout item=column();item.setPadding(dp(8),dp(8),dp(8),dp(12));item.setBackgroundColor(Color.WHITE);TextView file=text(r.file.name+" · "+Search.time(r.start)+"–"+Search.time(r.end),15);file.setTypeface(null,1);item.addView(file);item.addView(text(r.excerpt,15));item.addView(text(t("Кратко (цитата): ","Brief (quote): ")+r.summary,12));item.addView(button(t("Контекст и прослушивание","Context and playback"),()->details(r)));resultList.addView(item);}
        }catch(Exception e){toast(e.getMessage());}}
    void details(Result r){JSONArray segments=r.file.segments();StringBuilder context=new StringBuilder();double end=r.end;for(int i=0;i<segments.length();i++){JSONObject s=segments.optJSONObject(i);if(s.optDouble("end")<r.start-10||s.optDouble("start")>r.end+30)continue;context.append(Search.time(s.optDouble("start"))).append("  ").append(s.optString("text")).append("\n\n");end=Math.max(end,s.optDouble("end"));}double finish=end;TextView content=text(t("Ближайшие реплики: 10 секунд до и 30 после. Границы темы определите по разговору.\n\n","Nearby speech: 10 seconds before and 30 after. Check the conversation to determine topic boundaries.\n\n")+context,16);content.setTextIsSelectable(true);content.setPadding(dp(18),dp(8),dp(18),dp(8));ScrollView scroll=new ScrollView(this);scroll.addView(content);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(r.file.name).setView(scroll).setPositiveButton(t("Слушать","Play"),null).setNeutralButton(t("Стоп","Stop"),(d,w)->stopAudio()).setNegativeButton(t("Закрыть","Close"),(d,w)->stopAudio()).create();dialog.setOnDismissListener(d->stopAudio());dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->play(r.file.uri,r.start,finish)));dialog.show();}
    void play(String uri,double start,double end){stopAudio();try{player=new MediaPlayer();player.setDataSource(this,Uri.parse(uri));player.setOnPreparedListener(p->{p.seekTo((long)(start*1000),MediaPlayer.SEEK_CLOSEST);p.start();handler.postDelayed(this::stopAudio,(long)((end-start)*1000));});player.setOnCompletionListener(p->stopAudio());player.setOnErrorListener((p,a,b)->{toast(t("Не удалось воспроизвести","Could not play audio"));stopAudio();return true;});player.prepareAsync();}catch(Exception e){toast(e.getMessage());stopAudio();}}
    void stopAudio(){handler.removeCallbacksAndMessages(null);if(player!=null){player.release();player=null;}}
    void export(){search();if(matches.isEmpty()){toast(t("Нет результатов для экспорта","No results to export"));return;}StringBuilder out=new StringBuilder("\uFEFF");String[] columns=language.equals("ru")?new String[]{"Файл","Время в записи","Фрагмент разговора","Кратко (цитата)"}:new String[]{"File","Time in recording","Conversation excerpt","Brief (quote)"};for(int i=0;i<4;i++)out.append(i==0?"":",").append(Search.csv(columns[i]));out.append("\r\n");for(Result r:matches)out.append(Search.csv(r.file.name)).append(',').append(Search.csv(Search.time(r.start)+"–"+Search.time(r.end))).append(',').append(Search.csv(r.excerpt)).append(',').append(Search.csv(r.summary)).append("\r\n");csv=out.toString();startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("text/csv").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"AudioDetect-results.csv"),EXPORT);}
    void toast(String message){Toast.makeText(this,message,Toast.LENGTH_LONG).show();}
    @Override protected void onDestroy(){unregisterReceiver(events);stopAudio();if(library!=null)library.close();super.onDestroy();}
}
